  // allowlist has no `balance` field, so filter by paidStatus != CLOSED (OPEN or PARTIAL).
  const invoicesQuery = useInvoices({
    page: 1,
    limit: 200,
    sort: "number:desc",
    filterRows: [{ id: "payment-outstanding", join: "and", field: "paidStatus", operator: "neq", value: "CLOSED" }],
  });
