"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { Bookmark, BookmarkPlus, Check, ChevronDown, Trash2 } from "lucide-react";

import { ConfirmDeleteButton } from "@/components/app-shell/confirm-delete-button";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { createFilterRowId, countCompleteFilterRows } from "@/lib/table/filter-builder";
import type { TableFilterFieldDefinition, TableFilterRowState } from "@/lib/table/filter-types";
import { useFilterPresets } from "@/lib/filter-presets/hooks/use-filter-presets";
import type { FilterPreset } from "@/lib/filter-presets/types";
import { useTranslation } from "@/lib/i18n";
import { cn } from "@/lib/utils";

export type FilterPresetMenuProps = {
  /** Unique localStorage scope, typically the feature name (e.g. "customers"). */
  storageKey: string;
  /** Current advanced-filter rows to capture when saving a preset. */
  rows: TableFilterRowState[];
  /** Field definitions used to determine whether the current rows are saveable. */
  fields?: TableFilterFieldDefinition[];
  /** Applies a preset's rows (fresh row ids are generated before this is called). */
  onApply: (rows: TableFilterRowState[]) => void;
  className?: string;
};

const controlClassName =
  "inline-flex h-7 shrink-0 items-center gap-1.5 rounded-md border border-input bg-background px-2 text-xs font-medium text-foreground shadow-xs transition-colors hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:bg-background";

export function FilterPresetMenu({
  storageKey,
  rows,
  fields,
  onApply,
  className,
}: FilterPresetMenuProps) {
  const { t } = useTranslation();
  const { presets, isLoading, isMutating, savePreset, deletePreset } = useFilterPresets(storageKey);
  const [loadOpen, setLoadOpen] = useState(false);
  const [saveOpen, setSaveOpen] = useState(false);
  const [draftName, setDraftName] = useState("");
  const [presetPendingDelete, setPresetPendingDelete] = useState<FilterPreset | null>(null);
  const saveInputRef = useRef<HTMLInputElement>(null);

  const completeRowCount = countCompleteFilterRows(rows, fields);
  const canSave = completeRowCount > 0;

  useEffect(() => {
    if (!saveOpen) {
      setDraftName("");
    }
  }, [saveOpen]);

  useEffect(() => {
    if (saveOpen) {
      saveInputRef.current?.focus();
    }
  }, [saveOpen]);

  const presetsLabel = useMemo(
    () =>
      presets.length > 0
        ? t("common.table.filterPresets.presetsWithCount", { count: presets.length })
        : t("common.table.filterPresets.presets"),
    [presets.length, t],
  );

  function applyPreset(preset: { rows: TableFilterRowState[] }) {
    const clonedRows = preset.rows.map((row) => ({ ...row, id: createFilterRowId() }));
    onApply(clonedRows);
    setLoadOpen(false);
  }

  function handleSave() {
    const name = draftName.trim();
    if (!name || !canSave) return;
    savePreset(name, rows);
    setDraftName("");
    setSaveOpen(false);
  }

  function requestDeletePreset(preset: FilterPreset) {
    setLoadOpen(false);
    setPresetPendingDelete(preset);
  }

  function closeDeleteDialog() {
    if (isMutating) return;
    setPresetPendingDelete(null);
  }

  function confirmDeletePreset() {
    if (!presetPendingDelete) return;
    deletePreset(presetPendingDelete.id);
    setPresetPendingDelete(null);
  }

  return (
    <div className={cn("flex items-center gap-2", className)}>
      {/* Save current filters as a preset */}
      <Popover open={saveOpen} onOpenChange={(next) => setSaveOpen(next && canSave)}>
        <PopoverTrigger asChild>
          <button
            type="button"
            disabled={!canSave}
            className={controlClassName}
            aria-label={t("common.table.filterPresets.saveAria")}
            title={
              canSave
                ? t("common.table.filterPresets.saveTitle")
                : t("common.table.filterPresets.saveDisabledTitle")
            }
          >
            <BookmarkPlus className="h-3.5 w-3.5" />
            {t("common.table.filterPresets.save")}
          </button>
        </PopoverTrigger>
        <PopoverContent
          align="end"
          sideOffset={6}
          className="z-[110] w-64 p-3"
          onMouseDown={(event) => event.stopPropagation()}
          onOpenAutoFocus={(event) => event.preventDefault()}
        >
          <div className="space-y-2">
            <p className="text-xs font-medium text-foreground">
              {t("common.table.filterPresets.saveDialogTitle")}
            </p>
            <Input
              ref={saveInputRef}
              value={draftName}
              onChange={(event) => setDraftName(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter") {
                  event.preventDefault();
                  handleSave();
                } else if (event.key === "Escape") {
                  event.preventDefault();
                  setSaveOpen(false);
                }
              }}
              placeholder={t("common.table.filterPresets.namePlaceholder")}
              className="h-8 text-sm"
            />
            <div className="flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="h-7 px-2 text-xs"
                onClick={() => setSaveOpen(false)}
              >
                {t("common.actions.cancel")}
              </Button>
              <Button
                type="button"
                size="sm"
                className="h-7 px-3 text-xs"
                disabled={!draftName.trim() || isMutating}
                onClick={handleSave}
              >
                {t("common.actions.save")}
              </Button>
            </div>
          </div>
        </PopoverContent>
      </Popover>

      {/* Load a saved preset via searchable dropdown */}
      <Popover open={loadOpen} onOpenChange={setLoadOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            className={controlClassName}
            aria-label={t("common.table.filterPresets.loadAria")}
          >
            <Bookmark className="h-3.5 w-3.5" />
            {presetsLabel}
            <ChevronDown
              className={cn("h-3.5 w-3.5 transition-transform", loadOpen && "rotate-180")}
            />
          </button>
        </PopoverTrigger>
        <PopoverContent
          align="end"
          sideOffset={6}
          className="z-[110] w-64 p-0"
          onMouseDown={(event) => event.stopPropagation()}
        >
          {presets.length === 0 && isLoading ? (
            <p className="px-3 py-4 text-center text-xs text-muted-foreground">
              {t("common.table.filterPresets.loading")}
            </p>
          ) : presets.length > 0 ? (
            <Command>
              <CommandInput placeholder={t("common.table.filterPresets.searchPlaceholder")} />
              <CommandList className="max-h-56">
                <CommandEmpty>{t("common.table.filterPresets.noResults")}</CommandEmpty>
                <CommandGroup heading={t("common.table.filterPresets.savedHeading")}>
                  {presets.map((preset) => (
                    <CommandItem
                      key={preset.id}
                      value={preset.name}
                      onSelect={() => applyPreset(preset)}
                      className="justify-between gap-2"
                    >
                      <span className="flex min-w-0 items-center gap-2">
                        <Check className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                        <span className="truncate">{preset.name}</span>
                      </span>
                      <button
                        type="button"
                        aria-label={t("common.table.filterPresets.deleteAria", { name: preset.name })}
                        className="shrink-0 rounded p-1 text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"
                        onMouseDown={(event) => {
                          event.preventDefault();
                          event.stopPropagation();
                        }}
                        onClick={(event) => {
                          event.preventDefault();
                          event.stopPropagation();
                          requestDeletePreset(preset);
                        }}
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
            </Command>
          ) : (
            <p className="px-3 py-4 text-center text-xs text-muted-foreground">
              {t("common.table.filterPresets.emptyState")}
            </p>
          )}
        </PopoverContent>
      </Popover>

      <Dialog
        open={presetPendingDelete !== null}
        onOpenChange={(open) => !open && closeDeleteDialog()}
      >
        <DialogContent className="z-[60]">
          <DialogHeader>
            <DialogTitle>{t("common.table.filterPresets.deleteTitle")}</DialogTitle>
            <DialogDescription>
              {presetPendingDelete
                ? t("common.table.filterPresets.deleteDescription", {
                    name: presetPendingDelete.name,
                    cannotBeUndone: t("common.dialogs.cannotBeUndone"),
                  })
                : null}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={closeDeleteDialog} disabled={isMutating}>
              {t("common.actions.cancel")}
            </Button>
            <ConfirmDeleteButton isPending={isMutating} onClick={confirmDeletePreset} />
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

