"use client";

import { useForm, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { branchFormSchema } from "@/lib/branches/schemas/branch.schema";
import { Building2, MapPin, Phone, Settings } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { useFormEnterNavigation } from "@/hooks/use-form-enter-navigation";
import { AddressAutocompleteInput } from "@/components/addresses/address-autocomplete-input";
import { FormBody, FormFooter, FormSection } from "@/components/forms/form-shell";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { SearchableSelect } from "@/components/ui/searchable-select";
import { PhoneListEditor } from "@/components/phones/phone-list-editor";
import { useTranslation } from "@/lib/i18n";
import { useIsGoogleMapsConfigured } from "@/lib/company/hooks/use-current-company";
import {
  type BranchAddress,
  type BranchFormValues,
  type BranchSettings,
  createEmptyBranchForm,
} from "@/lib/branches/types";
import type { ParsedPlaceAddress } from "@/lib/customers/types";

type BranchFormProps = {
  initialValues?: BranchFormValues;
  isEditing?: boolean;
  submitLabel: string;
  isSubmitting?: boolean;
  externalError?: string | null;
  onSubmit: (values: BranchFormValues) => void | Promise<void>;
  onCancel: () => void;
};

export function BranchForm({
  initialValues,
  submitLabel,
  isSubmitting = false,
  externalError = null,
  onSubmit,
  onCancel,
}: BranchFormProps) {
  const { t } = useTranslation();
  const googleMapsConfigured = useIsGoogleMapsConfigured();
  const { control, reset, setValue, getValues, handleSubmit, formState: { errors } } = useForm<BranchFormValues>({
    defaultValues: initialValues ?? createEmptyBranchForm(), resolver: zodResolver(branchFormSchema),
  });
  const values = useWatch({ control }) as BranchFormValues;
  const [manualAddressEntry, setManualAddressEntry] = useState(false);
  const handleEnterNavigation = useFormEnterNavigation();

  const booleanOptions = useMemo(
    () => [
      { value: "false", label: t("branches.enums.boolean.false") },
      { value: "true", label: t("branches.enums.boolean.true") },
    ],
    [t],
  );

  useEffect(() => {
    reset(initialValues ?? createEmptyBranchForm());
    setManualAddressEntry(false);
  }, [initialValues, reset]);

  function updateField<K extends keyof BranchFormValues>(key: K, value: BranchFormValues[K]) {
    setValue<keyof BranchFormValues>(key, value, { shouldDirty: true, shouldValidate: true });
  }
  function updateAddressField<K extends keyof BranchAddress>(key: K, value: BranchAddress[K]) {
    updateField("address", { ...getValues("address"), [key]: value, ...(["address1", "city", "state", "zipcode", "country"].includes(key) ? { location: null } : {}) });
  }
  function applyPlaceToAddress(place: ParsedPlaceAddress) {
    const address = getValues("address");
    updateField("address", { ...address, address1: place.address1 || address.address1, city: place.city || address.city, state: place.state || address.state, zipcode: place.zipcode || address.zipcode, country: place.country || address.country, location: place.location ?? null });
  }
  function updateSettingsField<K extends keyof BranchSettings>(key: K, value: BranchSettings[K]) {
    updateField("settings", { ...getValues("settings"), [key]: value });
  }

  const validationError =
    errors.name?.message || (Object.keys(values.settings) as Array<keyof BranchSettings>).map((key) => errors.settings?.[key]?.message).find(Boolean);

  return (
    <form onSubmit={handleSubmit(onSubmit)} onKeyDown={handleEnterNavigation} className="flex min-h-0 flex-1 flex-col">
      <FormBody isBusy={isSubmitting}>
        <FormSection icon={Building2} title={t("branches.form.sections.branch")}>
          <div className="space-y-2.5">
            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="min-w-0 w-full flex-1 space-y-1">
                <Label htmlFor="name">
                  {t("branches.form.fields.name")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="name"
                  value={values.name}
                  onChange={(event) => updateField("name", event.target.value)}
                  required
                />
              </div>
              <div className="min-w-0 flex-1 space-y-1">
                <Label htmlFor="code">{t("branches.form.fields.code")}</Label>
                <Input id="code" value={values.code} onChange={(event) => updateField("code", event.target.value)} />
              </div>
            </div>

            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="type">{t("branches.form.fields.type")}</Label>
                <Input id="type" value={values.type} onChange={(event) => updateField("type", event.target.value)} />
              </div>
              <div className="space-y-1">
                <Label htmlFor="logo">{t("branches.form.fields.logo")}</Label>
                <Input id="logo" value={values.logo} onChange={(event) => updateField("logo", event.target.value)} />
              </div>
            </div>

            <div className="space-y-1">
              <Label htmlFor="disclaimer">{t("branches.form.fields.disclaimer")}</Label>
              <Input
                id="disclaimer"
                value={values.disclaimer}
                onChange={(event) => updateField("disclaimer", event.target.value)}
              />
            </div>
          </div>
        </FormSection>

        <FormSection
          icon={MapPin}
          title={t("branches.form.sections.address")}
          action={
            <button
              type="button"
              className="text-xs text-muted-foreground underline-offset-4 hover:text-foreground hover:underline"
              onClick={() => setManualAddressEntry((current) => !current)}
            >
              {manualAddressEntry ? t("common.address.useGoogle") : t("common.address.useManual")}
            </button>
          }
        >
          <div className="space-y-2.5">
            <div className="flex items-end gap-2">
              <div className="min-w-0 flex-1 space-y-1">
                <Label htmlFor="address-address1" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.address1")}
                </Label>
                <AddressAutocompleteInput
                  id="address-address1"
                  value={values.address.address1}
                  onValueChange={(value) => updateAddressField("address1", value)}
                  onPlaceSelected={applyPlaceToAddress}
                  placeholder={t("branches.form.fields.address1")}
                  allowManualEntry
                  className="w-full"
                  onManualEntryChange={setManualAddressEntry}
                  manualEntry={manualAddressEntry}
                  manualEntryTogglePosition="none"
                />
              </div>
              <div className="w-24 shrink-0 space-y-1 sm:w-32">
                <Label htmlFor="address-apartment" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.apartment")}
                </Label>
                <Input
                  id="address-apartment"
                  value={values.address.apartment}
                  onChange={(event) => updateAddressField("apartment", event.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1">
              <Input
                id="address-address2"
                value={values.address.address2}
                onChange={(event) => updateAddressField("address2", event.target.value)}
                placeholder={t("branches.form.fields.address2")}
                autoComplete="off"
              />
            </div>

            <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-4">
              <div className="space-y-1">
                <Label htmlFor="address-city" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.city")}
                </Label>
                <Input
                  id="address-city"
                  value={values.address.city}
                  onChange={(event) => updateAddressField("city", event.target.value)}
                  disabled={googleMapsConfigured && !manualAddressEntry}
                  readOnly={googleMapsConfigured && !manualAddressEntry}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="address-state" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.state")}
                </Label>
                <Input
                  id="address-state"
                  value={values.address.state}
                  onChange={(event) => updateAddressField("state", event.target.value.toUpperCase())}
                  disabled={googleMapsConfigured && !manualAddressEntry}
                  readOnly={googleMapsConfigured && !manualAddressEntry}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="address-zipcode" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.zipcode")}
                </Label>
                <Input
                  id="address-zipcode"
                  value={values.address.zipcode}
                  onChange={(event) => updateAddressField("zipcode", event.target.value)}
                  disabled={googleMapsConfigured && !manualAddressEntry}
                  readOnly={googleMapsConfigured && !manualAddressEntry}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="address-country" className="text-xs text-muted-foreground">
                  {t("branches.form.fields.country")}
                </Label>
                <Input
                  id="address-country"
                  value={values.address.country}
                  onChange={(event) => updateAddressField("country", event.target.value.toUpperCase())}
                  disabled={googleMapsConfigured && !manualAddressEntry}
                  readOnly={googleMapsConfigured && !manualAddressEntry}
                />
              </div>
            </div>
          </div>
        </FormSection>

        <FormSection icon={Phone} title={t("branches.form.sections.contact")}>
          <div className="space-y-1">
            <Label>{t("branches.form.fields.phones")}</Label>
            <PhoneListEditor
              idPrefix="branch-phone"
              compact
              phones={values.phones}
              onChange={(phones) => updateField("phones", phones)}
            />
          </div>
        </FormSection>

        <FormSection icon={Settings} title={t("branches.form.sections.settings")}>
          <div className="space-y-2.5">
            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="settings-labelPrefix">{t("branches.form.fields.labelPrefix")}</Label>
                <Input
                  id="settings-labelPrefix"
                  value={values.settings.labelPrefix}
                  onChange={(event) => updateSettingsField("labelPrefix", event.target.value)}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="settings-roundDecimalPlaces">{t("branches.form.fields.roundDecimalPlaces")}</Label>
                <Input
                  id="settings-roundDecimalPlaces"
                  type="number"
                  value={values.settings.roundDecimalPlaces}
                  onChange={(event) => updateSettingsField("roundDecimalPlaces", Number(event.target.value) || 0)}
                />
              </div>
            </div>

            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="settings-defaultLabelStatus">{t("branches.form.fields.defaultLabelStatus")}</Label>
                <Input
                  id="settings-defaultLabelStatus"
                  type="number"
                  value={values.settings.defaultLabelStatus}
                  onChange={(event) => updateSettingsField("defaultLabelStatus", Number(event.target.value) || 0)}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="settings-imageResampleBy">{t("branches.form.fields.imageResampleBy")}</Label>
                <Input
                  id="settings-imageResampleBy"
                  type="number"
                  value={values.settings.imageResampleBy}
                  onChange={(event) => updateSettingsField("imageResampleBy", Number(event.target.value) || 0)}
                />
              </div>
            </div>

            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="settings-s3Profile">{t("branches.form.fields.s3Profile")}</Label>
                <Input
                  id="settings-s3Profile"
                  value={values.settings.s3Profile}
                  onChange={(event) => updateSettingsField("s3Profile", event.target.value)}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="settings-s3BucketName">{t("branches.form.fields.s3BucketName")}</Label>
                <Input
                  id="settings-s3BucketName"
                  value={values.settings.s3BucketName}
                  onChange={(event) => updateSettingsField("s3BucketName", event.target.value)}
                />
              </div>
            </div>

            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="settings-s3BucketFolder">{t("branches.form.fields.s3BucketFolder")}</Label>
                <Input
                  id="settings-s3BucketFolder"
                  value={values.settings.s3BucketFolder}
                  onChange={(event) => updateSettingsField("s3BucketFolder", event.target.value)}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="settings-s3ShareLinkExpireMinutes">
                  {t("branches.form.fields.s3ShareLinkExpireMinutes")}
                </Label>
                <Input
                  id="settings-s3ShareLinkExpireMinutes"
                  type="number"
                  value={values.settings.s3ShareLinkExpireMinutes}
                  onChange={(event) =>
                    updateSettingsField("s3ShareLinkExpireMinutes", Number(event.target.value) || 0)
                  }
                />
              </div>
            </div>

            <div className="grid gap-2.5 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="settings-invoiceCreatedThruIncomeStatement">
                  {t("branches.form.fields.invoiceCreatedThruIncomeStatement")}
                </Label>
                <SearchableSelect
                  id="settings-invoiceCreatedThruIncomeStatement"
                  value={values.settings.invoiceCreatedThruIncomeStatement ? "true" : "false"}
                  onValueChange={(next) =>
                    updateSettingsField("invoiceCreatedThruIncomeStatement", next === "true")
                  }
                  options={booleanOptions}
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="settings-printLabelCount">{t("branches.form.fields.printLabelCount")}</Label>
                <SearchableSelect
                  id="settings-printLabelCount"
                  value={values.settings.printLabelCount ? "true" : "false"}
                  onValueChange={(next) => updateSettingsField("printLabelCount", next === "true")}
                  options={booleanOptions}
                />
              </div>
            </div>
          </div>
        </FormSection>
      </FormBody>

      <FormFooter
        error={externalError || (validationError ? t(validationError) : undefined)}
        submitLabel={submitLabel}
        isSubmitting={isSubmitting}
        onCancel={onCancel}
      />
    </form>
  );
}

"use client";

import { Container, Ship } from "lucide-react";
import { useEffect, useState } from "react";

import { useFormEnterNavigation } from "@/hooks/use-form-enter-navigation";
import { FormBody, FormFooter, FormSection } from "@/components/forms/form-shell";
import { DateInput } from "@/components/ui/date-input";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useTranslation } from "@/lib/i18n";
import {
  createEmptyContainerForm,
  type ContainerFormValues,
} from "@/lib/containers/types";

type ContainerFormProps = {
  initialValues?: ContainerFormValues;
  isEditing?: boolean;
  suggestedContainerName?: string;
  submitLabel: string;
  isSubmitting?: boolean;
  externalError?: string | null;
  onSubmit: (values: ContainerFormValues) => void;
  onCancel: () => void;
};

export function ContainerForm({
  initialValues,
  isEditing = false,
  suggestedContainerName,
  submitLabel,
  isSubmitting = false,
  externalError = null,
  onSubmit,
  onCancel,
}: ContainerFormProps) {
  const { t } = useTranslation();
  const [values, setValues] = useState<ContainerFormValues>(initialValues ?? createEmptyContainerForm());
  const [validationError, setValidationError] = useState<string | null>(null);
  const handleEnterNavigation = useFormEnterNavigation();

  useEffect(() => {
    const base = initialValues ?? createEmptyContainerForm();
    setValues(
      !isEditing && suggestedContainerName && !base.name
        ? { ...base, name: suggestedContainerName }
        : base,
    );
    setValidationError(null);
  }, [initialValues, isEditing, suggestedContainerName]);

  function updateField<K extends keyof ContainerFormValues>(key: K, value: ContainerFormValues[K]) {
    setValues((current) => ({ ...current, [key]: value }));
    setValidationError(null);
  }

  function getValidationError(): string | null {
    if (!values.name.trim()) {
      return t("containers.form.validation.nameRequired");
    }

    if (!values.booking.trim()) {
      return t("containers.form.validation.bookingRequired");
    }

    if (values.cost.trim()) {
      const cost = Number(values.cost);
      if (!Number.isFinite(cost) || cost < 0) {
        return t("containers.form.validation.costInvalid");
      }
    }

    return null;
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    const error = getValidationError();
    if (error) {
      setValidationError(error);
      return;
    }

    setValidationError(null);
    onSubmit(values);
  }

  return (
    <form onSubmit={handleSubmit} onKeyDown={handleEnterNavigation} className="flex min-h-0 flex-1 flex-col">
      <FormBody workflow isBusy={isSubmitting}>
        <div className="grid items-start gap-5 @4xl:grid-cols-2">
          <FormSection variant="card" icon={Container} title={`01 · ${t("containers.form.sections.container")}`} description={t("containers.form.design.container")}>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="name">
                  {t("containers.form.fields.name")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="name"
                  value={values.name}
                  onChange={(event) => updateField("name", event.target.value)}
                  placeholder={t("containers.form.placeholders.name")}
                  required
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="containerNumber">{t("containers.form.fields.containerNumber")}</Label>
                <Input
                  id="containerNumber"
                  value={values.containerNumber}
                  onChange={(event) => updateField("containerNumber", event.target.value.toUpperCase())}
                  placeholder={t("containers.form.placeholders.containerNumber")}
                  className="font-mono text-xs"
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="booking">
                  {t("containers.form.fields.booking")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="booking"
                  value={values.booking}
                  onChange={(event) => updateField("booking", event.target.value)}
                  placeholder={t("containers.form.placeholders.booking")}
                  required
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="sealNumber">{t("containers.form.fields.sealNumber")}</Label>
                <Input
                  id="sealNumber"
                  value={values.sealNumber}
                  onChange={(event) => updateField("sealNumber", event.target.value)}
                  placeholder={t("containers.form.placeholders.sealNumber")}
                />
              </div>

              <div className="space-y-1 sm:col-span-2">
                <Label htmlFor="itn">{t("containers.form.fields.itn")}</Label>
                <Input
                  id="itn"
                  value={values.itn}
                  onChange={(event) => updateField("itn", event.target.value)}
                  placeholder={t("containers.form.placeholders.itn")}
                  className="font-mono text-xs"
                />
              </div>
            </div>
          </FormSection>

          <FormSection variant="card" icon={Ship} title={`02 · ${t("containers.form.sections.logistics")}`} description={t("containers.form.design.logistics")}>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1">
                <Label htmlFor="broker">{t("containers.form.fields.broker")}</Label>
                <Input
                  id="broker"
                  value={values.broker}
                  onChange={(event) => updateField("broker", event.target.value)}
                  placeholder={t("containers.form.placeholders.broker")}
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="company">{t("containers.form.fields.company")}</Label>
                <Input
                  id="company"
                  value={values.company}
                  onChange={(event) => updateField("company", event.target.value)}
                  placeholder={t("containers.form.placeholders.company")}
                />
              </div>

              <div className="space-y-1 sm:col-span-2">
                <Label htmlFor="cost">{t("containers.form.fields.cost")}</Label>
                <Input
                  id="cost"
                  type="number"
                  min={0}
                  step="0.01"
                  value={values.cost}
                  onChange={(event) => updateField("cost", event.target.value)}
                  placeholder={t("containers.form.placeholders.cost")}
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="departureDate">{t("containers.form.fields.departureDate")}</Label>
                <DateInput
                  id="departureDate"
                  value={values.departureDate}
                  onChange={(event) => updateField("departureDate", event.target.value)}
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="arrivalDate">{t("containers.form.fields.arrivalDate")}</Label>
                <DateInput
                  id="arrivalDate"
                  value={values.arrivalDate}
                  onChange={(event) => updateField("arrivalDate", event.target.value)}
                />
              </div>
            </div>
          </FormSection>
        </div>
      </FormBody>

      <FormFooter
        error={validationError ?? externalError}
        submitLabel={submitLabel}
        isSubmitting={isSubmitting}
        onCancel={onCancel}
      />
    </form>
  );
}

