"use client";

import {
  MapPin,
  Phone as PhoneIcon,
  Plus,
  Star,
  Trash2,
  User,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

import {
  getNavigableFormFields,
  selectFormFieldText,
  useFormEnterNavigation,
} from "@/hooks/use-form-enter-navigation";
import { useIsGoogleMapsConfigured } from "@/lib/company/hooks/use-current-company";
import { FormBody, FormFooter, FormSection } from "@/components/forms/form-shell";
import { PhoneListEditor } from "@/components/phones/phone-list-editor";
import {
  REQUIRED_PHONE_DIGITS,
  createEmptyRecordPhone,
  isCompletePhoneNumber,
} from "@/lib/phones/phones";
import { AddressAutocompleteInput } from "@/components/addresses/address-autocomplete-input";
import { AddressVerificationBadge } from "@/components/addresses/address-verification-badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { SearchableSelect } from "@/components/ui/searchable-select";
import { cn } from "@/lib/utils";
import { CUSTOMER_TYPE_SENDER, isCustomerSenderType } from "@/lib/customers/customer-type";
import { useTranslation } from "@/lib/i18n";
import {
  findDominicanCity,
  getDominicanCityOptions,
  type DominicanCity,
} from "@/lib/customers/dominican-cities";
import {
  CUSTOMER_TYPE_OPTIONS,
  applyCustomerTypeBranch,
  applyPlaceToCoreAddress,
  clearCoreAddressVerification,
  coreAddressHasContent,
  coreAddressRequiresVerification,
  createEmptyCustomerCoreAddress,
  createEmptyCustomerForm,
  findDuplicateCustomerAddressIndex,
  findDuplicateCustomerPhoneIndex,
  getCustomerAddressDuplicateKey,
  getDefaultCountryForPortalBranch,
  getPortalBranchForCustomerType,
  isAddressVerified,
  normalizeCustomerFormValues,
  normalizeCustomerType,
  normalizeCustomerAddresses,
  setCustomerFormPrimaryAddress,
  validateCustomerFormValues,
  type CustomerCoreAddress,
  type CustomerFormValues,
  type ParsedPlaceAddress,
} from "@/lib/customers/types";

/** Manual edits to these fields invalidate a prior Google verification. */
const VERIFICATION_SENSITIVE_FIELDS: (keyof CustomerCoreAddress)[] = [
  "address1",
  "city",
  "state",
  "zipcode",
  "country",
];

/** Capitalize the first letter of every word, preserving the rest as typed. */
function capitalizeWords(value: string): string {
  return value.replace(/(^|\s)(\p{L})/gu, (_match, boundary, letter) => boundary + letter.toUpperCase());
}

function focusFormField(id: string) {
  requestAnimationFrame(() => {
    document.getElementById(id)?.focus();
  });
}

type CustomerFormProps = {
  initialValues?: CustomerFormValues;
  isEditing?: boolean;
  submitLabel: string;
  isSubmitting?: boolean;
  externalError?: string | null;
  /** Lock the customer type (e.g. when adding a sender/receiver from the order form). */
  lockCustomerType?: boolean;
  /** Reveal addresses and append an empty row so the user can add a new one. */
  startWithNewAddress?: boolean;
  /** Append an empty phone row so the user can add a new one. */
  startWithNewPhone?: boolean;
  /** A new navigation request for an already-open customer form. */
  entryNonce?: number;
  /**
   * Index among addresses that have content. Focus that street field instead of
   * the name when the form opens from "Update address".
   */
  focusAddressIndex?: number;
  onSubmit: (values: CustomerFormValues) => void | Promise<void>;
  onCancel: () => void;
};

function withTrailingEmptyAddress(values: CustomerFormValues): CustomerFormValues {
  const last = values.addresses[values.addresses.length - 1];
  if (last && !coreAddressRequiresVerification(last)) {
    return values;
  }

  const country =
    values.addresses.find((entry) => entry.isPrimary)?.country ??
    values.addresses[0]?.country ??
    "US";

  return {
    ...values,
    addresses: [...values.addresses, createEmptyCustomerCoreAddress(country, false)],
  };
}

function withTrailingEmptyPhone(values: CustomerFormValues): CustomerFormValues {
  const last = values.phones[values.phones.length - 1];
  if (last && !last.number.trim()) {
    return values;
  }

  return {
    ...values,
    phones: [...values.phones, createEmptyRecordPhone(false)],
  };
}

function resolveExistingAddressFocusIndex(
  addresses: CustomerCoreAddress[],
  contentIndex: number | null | undefined,
): number | null {
  if (contentIndex == null || contentIndex < 0) return null;
  const contentIndexes = addresses
    .map((address, index) => (coreAddressHasContent(address) ? index : -1))
    .filter((index) => index >= 0);
  const formIndex = contentIndexes[contentIndex];
  return formIndex == null ? null : formIndex;
}

function initializeCustomerFormState(
  initialValues: CustomerFormValues | undefined,
  startWithNewAddress: boolean,
  startWithNewPhone = false,
  focusAddressIndex?: number,
) {
  const base = normalizeCustomerFormValues(initialValues ?? createEmptyCustomerForm());
  let values = startWithNewAddress ? withTrailingEmptyAddress(base) : base;
  values = startWithNewPhone ? withTrailingEmptyPhone(values) : values;
  const existingAddressFocusIndex = startWithNewAddress
    ? null
    : resolveExistingAddressFocusIndex(values.addresses, focusAddressIndex);

  return {
    values,
    showAddresses:
      startWithNewAddress ||
      existingAddressFocusIndex != null ||
      values.addresses.some(coreAddressRequiresVerification),
    pendingAddressFocusIndex: startWithNewAddress
      ? values.addresses.length - 1
      : existingAddressFocusIndex,
    pendingPhoneFocusIndex: startWithNewPhone ? values.phones.length - 1 : null,
  };
}

type AddressFieldGridProps = {
  idPrefix: string;
  address: CustomerCoreAddress;
  /** Sender = Google autocomplete; receiver = predetermined city list. */
  mode: "sender" | "receiver";
  onChange: (field: keyof CustomerCoreAddress, value: string) => void;
  onPlaceSelected: (place: ParsedPlaceAddress) => void;
  onCitySelected: (city: DominicanCity) => void;
};

const CITY_DROPDOWN_OPTIONS = getDominicanCityOptions();

function AddressFieldGrid({
  idPrefix,
  address,
  mode,
  onChange,
  onPlaceSelected,
  onCitySelected,
}: AddressFieldGridProps) {
  const { t } = useTranslation();
  const labels = {
    address1: t("customers.form.addressFields.address1"),
    address2: t("customers.form.addressFields.address2"),
    crossStreet: t("customers.form.addressFields.crossStreet"),
    apartment: t("customers.form.addressFields.apartment"),
    city: t("customers.form.addressFields.city"),
    cityProvince: t("customers.form.addressFields.cityProvince"),
    state: t("customers.form.addressFields.state"),
    zipcode: t("customers.form.addressFields.zipcode"),
    country: t("customers.form.addressFields.country"),
  };
  const dash = t("common.empty.dash");

  const cityOptions =
    address.city && !CITY_DROPDOWN_OPTIONS.some((option) => option.value === address.city)
      ? [{ value: address.city, label: address.city }, ...CITY_DROPDOWN_OPTIONS]
      : CITY_DROPDOWN_OPTIONS;

  const googleEnabled = useIsGoogleMapsConfigured();
  // Senders use Google autocomplete to fill city/state/zip, so we render those
  // as read-only text instead of editable fields.
  const senderAutoFill = mode === "sender" && googleEnabled;

  return (
    <div className="space-y-2.5">
      {/* Address line 1 + apartment, side by side like the phone rows. */}
      <div className="flex items-end gap-2">
        <div className="min-w-0 flex-1 space-y-1">
          <Label htmlFor={`${idPrefix}-address1`} className="text-xs text-muted-foreground">
            {labels.address1}
          </Label>
          {mode === "sender" ? (
            <AddressAutocompleteInput
              id={`${idPrefix}-address1`}
              value={address.address1}
              onValueChange={(value) => onChange("address1", value)}
              onPlaceSelected={onPlaceSelected}
              placeholder={t("customers.form.placeholders.streetAddress")}
            />
          ) : (
            <Input
              id={`${idPrefix}-address1`}
              value={address.address1}
              onChange={(event) => onChange("address1", event.target.value)}
              placeholder={t("customers.form.placeholders.streetAddressManual")}
            />
          )}
        </div>
        <div className="w-24 shrink-0 space-y-1 sm:w-32">
          <Label htmlFor={`${idPrefix}-apartment`} className="text-xs text-muted-foreground">
            {labels.apartment}
          </Label>
          <Input
            id={`${idPrefix}-apartment`}
            value={address.apartment}
            onChange={(event) => onChange("apartment", event.target.value)}
            placeholder={t("customers.form.placeholders.apartment")}
            autoComplete="off"
          />
        </div>
      </div>

      {/* Cross street sits below address line 1 + apartment for both senders and receivers. */}
      <div className="space-y-1">
        <Label htmlFor={`${idPrefix}-cross-street`} className="text-xs text-muted-foreground">
          {t("customers.form.placeholders.crossStreet")}
        </Label>
        <Input
          id={`${idPrefix}-cross-street`}
          value={address.address2}
          onChange={(event) => onChange("address2", event.target.value)}
          placeholder={t("customers.form.placeholders.crossStreet")}
          autoComplete="off"
        />
      </div>

      {senderAutoFill ? (
        <div className="space-y-1">
          <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-4">
            <div className="space-y-1">
              <Label htmlFor={`${idPrefix}-city`} className="text-xs text-muted-foreground">
                {labels.city}
              </Label>
              <Input
                id={`${idPrefix}-city`}
                value={address.city}
                placeholder={dash}
                disabled
                readOnly
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor={`${idPrefix}-state`} className="text-xs text-muted-foreground">
                {labels.state}
              </Label>
              <Input
                id={`${idPrefix}-state`}
                value={address.state}
                placeholder={dash}
                disabled
                readOnly
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor={`${idPrefix}-zipcode`} className="text-xs text-muted-foreground">
                {labels.zipcode}
              </Label>
              <Input
                id={`${idPrefix}-zipcode`}
                value={address.zipcode}
                placeholder={dash}
                disabled
                readOnly
              />
            </div>
            <div className="space-y-1">
              <Label htmlFor={`${idPrefix}-country`} className="text-xs text-muted-foreground">
                {labels.country}
              </Label>
              <Input
                id={`${idPrefix}-country`}
                value={address.country}
                placeholder={dash}
                disabled
                readOnly
              />
            </div>
          </div>
          {!isAddressVerified(address) ? (
            <p className="text-xs text-muted-foreground">
              {t("customers.form.address.googleHint")}
            </p>
          ) : null}
        </div>
      ) : mode === "receiver" ? (
        <div className="grid gap-2.5 sm:grid-cols-2">
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-city`} className="text-xs text-muted-foreground">
              {labels.cityProvince}
            </Label>
            <SearchableSelect
              id={`${idPrefix}-city`}
              value={address.city}
              searchPlaceholder={t("customers.form.placeholders.cityProvinceSearch")}
              onValueChange={(value) => {
                const match = findDominicanCity(value);
                if (match) {
                  onCitySelected(match);
                } else {
                  onChange("city", value);
                }
              }}
              options={cityOptions}
              placeholder={t("customers.form.placeholders.cityProvince")}
              mobileSheet
            />
          </div>
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-zipcode`} className="text-xs text-muted-foreground">
              {labels.zipcode}
            </Label>
            <Input
              id={`${idPrefix}-zipcode`}
              value={address.zipcode}
              onChange={(event) => onChange("zipcode", event.target.value)}
            />
          </div>
        </div>
      ) : (
        // Sender without Google configured: keep editable city/state/zip inputs.
        <div className="grid gap-2.5 sm:grid-cols-3">
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-city`} className="text-xs text-muted-foreground">
              {labels.city}
            </Label>
            <Input
              id={`${idPrefix}-city`}
              value={address.city}
              onChange={(event) => onChange("city", event.target.value)}
            />
          </div>
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-state`} className="text-xs text-muted-foreground">
              {labels.state}
            </Label>
            <Input
              id={`${idPrefix}-state`}
              value={address.state}
              onChange={(event) => onChange("state", event.target.value.toUpperCase())}
            />
          </div>
          <div className="space-y-1">
            <Label htmlFor={`${idPrefix}-zipcode`} className="text-xs text-muted-foreground">
              {labels.zipcode}
            </Label>
            <Input
              id={`${idPrefix}-zipcode`}
              value={address.zipcode}
              onChange={(event) => onChange("zipcode", event.target.value)}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export function CustomerForm({
  initialValues,
  isEditing = false,
  submitLabel,
  isSubmitting = false,
  externalError = null,
  lockCustomerType = false,
  startWithNewAddress = false,
  startWithNewPhone = false,
  entryNonce,
  focusAddressIndex,
  onSubmit,
  onCancel,
}: CustomerFormProps) {
  const { t } = useTranslation();
  const initialState = initializeCustomerFormState(
    initialValues,
    startWithNewAddress,
    startWithNewPhone,
    focusAddressIndex,
  );
  const [values, setValues] = useState<CustomerFormValues>(() => initialState.values);
  const [formError, setFormError] = useState<string | null>(null);
  // The address section stays collapsed until the user adds one (or when editing
  // a customer that already has address content).
  const [showAddresses, setShowAddresses] = useState(() => initialState.showAddresses);
  const [pendingAddressFocusIndex, setPendingAddressFocusIndex] = useState<number | null>(
    () => initialState.pendingAddressFocusIndex,
  );
  const [pendingPhoneFocusIndex, setPendingPhoneFocusIndex] = useState<number | null>(
    () => initialState.pendingPhoneFocusIndex,
  );
  const previousEntryNonce = useRef(entryNonce);
  const errorMessage = formError ?? externalError;
  const handleEnterNavigation = useFormEnterNavigation();

  useEffect(() => {
    const next = initializeCustomerFormState(
      initialValues,
      startWithNewAddress,
      startWithNewPhone,
      focusAddressIndex,
    );
    setValues(next.values);
    setShowAddresses(next.showAddresses);
    setPendingAddressFocusIndex(next.pendingAddressFocusIndex);
    setPendingPhoneFocusIndex(next.pendingPhoneFocusIndex);
    setFormError(null);
    // Reset only for a new entity/version so parent rerenders preserve typed input.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialValues?.id, initialValues?.updatedAt]);

  useEffect(() => {
    if (previousEntryNonce.current === entryNonce) return;
    previousEntryNonce.current = entryNonce;
    // Reopening a tab must retain its unsaved fields.
    if (startWithNewAddress) {
      const next = withTrailingEmptyAddress(values);
      setValues(next);
      setShowAddresses(true);
      setPendingAddressFocusIndex(next.addresses.length - 1);
    } else if (startWithNewPhone) {
      const next = withTrailingEmptyPhone(values);
      setValues(next);
      setPendingPhoneFocusIndex(next.phones.length - 1);
    } else if (focusAddressIndex != null) {
      const formIndex = resolveExistingAddressFocusIndex(values.addresses, focusAddressIndex);
      if (formIndex != null) {
        setShowAddresses(true);
        setPendingAddressFocusIndex(formIndex);
      }
    }
  }, [entryNonce, focusAddressIndex, startWithNewAddress, startWithNewPhone, values]);

  useEffect(() => {
    if (pendingAddressFocusIndex == null || !showAddresses) return;
    const index = pendingAddressFocusIndex;
    // Run after the form's first-field focus so the street field wins.
    const frame = window.requestAnimationFrame(() => {
      const input = document.getElementById(`address-${index}-address1`);
      if (!(input instanceof HTMLElement)) return;
      input.focus();
      input.scrollIntoView({ block: "nearest" });
      setPendingAddressFocusIndex(null);
    });
    return () => window.cancelAnimationFrame(frame);
  }, [pendingAddressFocusIndex, showAddresses, values.addresses.length]);

  useEffect(() => {
    if (pendingPhoneFocusIndex == null) return;
    const input = document.getElementById(`customer-phone-number-${pendingPhoneFocusIndex}`);
    if (!input) return;
    input.focus();
    setPendingPhoneFocusIndex(null);
  }, [pendingPhoneFocusIndex, values.phones.length]);

  function updateField<K extends keyof CustomerFormValues>(
    key: K,
    value: CustomerFormValues[K],
  ) {
    setValues((current) => {
      const next = { ...current, [key]: value };
      return key === "customerType" ? applyCustomerTypeBranch(next) : next;
    });
    setFormError(null);
  }

  /**
   * Switching customer type swaps the address mode (sender Google autocomplete ↔
   * receiver city list) and country, so any previously entered address no longer
   * applies. Reset back to the collapsed, default state.
   */
  function handleCustomerTypeChange(nextType: number) {
    if (normalizeCustomerType(values.customerType) === normalizeCustomerType(nextType)) {
      return;
    }

    setValues((current) => {
      const next = applyCustomerTypeBranch({ ...current, customerType: nextType });
      const emptyAddress = createEmptyCustomerCoreAddress(
        getDefaultCountryForPortalBranch(getPortalBranchForCustomerType(nextType)),
        true,
      );

      return {
        ...next,
        addresses: [emptyAddress],
      };
    });
    setShowAddresses(false);
    setFormError(null);
  }

  function applyAddressFieldEdit<K extends keyof CustomerCoreAddress>(
    address: CustomerCoreAddress,
    key: K,
    value: CustomerCoreAddress[K],
  ): CustomerCoreAddress {
    const next = { ...address, [key]: value };
    return VERIFICATION_SENSITIVE_FIELDS.includes(key)
      ? clearCoreAddressVerification(next)
      : next;
  }

  function updateAddressField<K extends keyof CustomerCoreAddress>(
    index: number,
    key: K,
    value: CustomerCoreAddress[K],
  ) {
    setValues((current) => ({
      ...current,
      addresses: current.addresses.map((entry, addressIndex) =>
        addressIndex === index ? applyAddressFieldEdit(entry, key, value) : entry,
      ),
    }));
    setFormError(null);
  }

  function applyPlaceToAddress(index: number, place: ParsedPlaceAddress) {
    setValues((current) => ({
      ...current,
      addresses: current.addresses.map((entry, addressIndex) =>
        addressIndex === index ? applyPlaceToCoreAddress(entry, place) : entry,
      ),
    }));
  }

  function applyCityToCoreAddress(
    address: CustomerCoreAddress,
    city: DominicanCity,
  ): CustomerCoreAddress {
    return { ...address, city: city.city, state: city.province };
  }

  function applyCityToAddress(index: number, city: DominicanCity) {
    setValues((current) => ({
      ...current,
      addresses: current.addresses.map((entry, addressIndex) =>
        addressIndex === index ? applyCityToCoreAddress(entry, city) : entry,
      ),
    }));
  }

  function getPrimaryAddressCountry(values: CustomerFormValues): string {
    return (
      values.addresses.find((entry) => entry.isPrimary)?.country ??
      values.addresses[0]?.country ??
      "US"
    );
  }

  function addAddress() {
    const newIndex = values.addresses.length;
    setValues((current) => ({
      ...current,
      addresses: [
        ...current.addresses,
        createEmptyCustomerCoreAddress(getPrimaryAddressCountry(current), false),
      ],
    }));
    setPendingAddressFocusIndex(newIndex);
  }

  /** Reveal the collapsed address section and focus the primary address. */
  function handleAddAddressClick() {
    if (!showAddresses) {
      setShowAddresses(true);
      const primaryIndex = Math.max(
        0,
        values.addresses.findIndex((entry) => entry.isPrimary),
      );
      setPendingAddressFocusIndex(primaryIndex < 0 ? 0 : primaryIndex);
      return;
    }
    addAddress();
  }

  function removeAddress(index: number) {
    const isLastAddress = values.addresses.length <= 1;

    setValues((current) => {
      if (current.addresses.length <= 1) {
        const empty = createEmptyCustomerCoreAddress(getPrimaryAddressCountry(current), true);
        return { ...current, addresses: [empty] };
      }

      const removedPrimary = current.addresses[index]?.isPrimary === true;
      const addresses = current.addresses
        .filter((_, addressIndex) => addressIndex !== index)
        .map((entry, addressIndex) => ({
          ...entry,
          isPrimary: removedPrimary ? addressIndex === 0 : entry.isPrimary,
        }));

      return {
        ...current,
        addresses: normalizeCustomerAddresses(addresses),
      };
    });

    if (isLastAddress) {
      setShowAddresses(false);
    }
  }

  /** Mark an address as primary without changing list order. */
  function setPrimaryAddress(index: number) {
    setValues((current) => setCustomerFormPrimaryAddress(current, index));
  }

  const isSender = isCustomerSenderType(values.customerType);
  const addressMode: "sender" | "receiver" = isSender ? "sender" : "receiver";
  const googleEnabled = useIsGoogleMapsConfigured();

  const savedAddressKeys =
    isEditing && initialValues
      ? new Set(initialValues.addresses.map(getCustomerAddressDuplicateKey).filter(Boolean))
      : null;

  function isAddressEntryComplete(address: CustomerCoreAddress): boolean {
    if (!isSender) return Boolean(address.city.trim());
    return googleEnabled ? isAddressVerified(address) : coreAddressRequiresVerification(address);
  }

  /**
   * Enter inside the phone or address sections moves to the next entry, or adds
   * one once the current entry is complete. It never submits; Save is manual.
   */
  function handleListEntryEnter(event: React.KeyboardEvent<HTMLFormElement>): boolean {
    if (event.key !== "Enter" || event.shiftKey || event.metaKey || event.ctrlKey || event.altKey) return false;
    if (event.defaultPrevented || event.nativeEvent.isComposing) return false;

    const target = event.target;
    if (!(target instanceof HTMLElement) || target.tagName === "BUTTON") return false;
    if (target.getAttribute("aria-expanded") === "true") return false;
    if (target.closest('[data-enter-navigation="ignore"]')) return false;

    const phoneMatch = /^customer-phone-number-(\d+)$/.exec(target.id);
    if (phoneMatch) {
      event.preventDefault();
      const index = Number(phoneMatch[1]);
      if (!isCompletePhoneNumber(values.phones[index]?.number ?? "")) return true;
      if (index + 1 < values.phones.length) {
        focusFormField(`customer-phone-number-${index + 1}`);
      } else {
        updateField("phones", [...values.phones, createEmptyRecordPhone(false)]);
        setPendingPhoneFocusIndex(values.phones.length);
      }
      return true;
    }

    const card = target.closest<HTMLElement>("[data-customer-address-index]");
    if (!card) return false;

    const fields = getNavigableFormFields(event.currentTarget);
    const position = fields.indexOf(target);
    if (position === -1) return false;
    event.preventDefault();

    const nextField = fields[position + 1];
    if (nextField && card.contains(nextField)) {
      nextField.focus();
      selectFormFieldText(nextField);
      return true;
    }

    const index = Number(card.dataset.customerAddressIndex);
    const address = values.addresses[index];
    if (!address) return true;
    if (!isAddressEntryComplete(address)) {
      focusFormField(isSender ? `address-${index}-address1` : `address-${index}-city`);
      return true;
    }
    if (index + 1 < values.addresses.length) {
      setPendingAddressFocusIndex(index + 1);
    } else {
      addAddress();
    }
    return true;
  }

  function handleFormKeyDown(event: React.KeyboardEvent<HTMLFormElement>) {
    if (handleListEntryEnter(event)) return;
    handleEnterNavigation(event);
  }

  // The single reason the customer can't be saved yet, evaluated in priority
  // order: name → first phone → any other started phone → any open address.
  // Senders need a verified address; receivers need a city selected.
  const blockReason: string | null = (() => {
    if (!values.name.trim()) {
      return t("customers.form.validation.nameRequired");
    }

    const firstPhone = values.phones[0];
    if (!firstPhone || !firstPhone.number.trim()) {
      return t("customers.form.validation.phoneRequired");
    }
    if (!isCompletePhoneNumber(firstPhone.number)) {
      return t("customers.form.validation.phoneDigits", { index: 1, digits: REQUIRED_PHONE_DIGITS });
    }

    for (let index = 1; index < values.phones.length; index += 1) {
      const phone = values.phones[index];
      if (phone.number.trim() && !isCompletePhoneNumber(phone.number)) {
        return t("customers.form.validation.phoneDigits", {
          index: index + 1,
          digits: REQUIRED_PHONE_DIGITS,
        });
      }
    }

    const duplicatePhoneIndex = findDuplicateCustomerPhoneIndex(values.phones);
    if (duplicatePhoneIndex >= 0) {
      return t("customers.form.validation.duplicatePhone", { index: duplicatePhoneIndex + 1 });
    }

    if (showAddresses) {
      for (let index = 0; index < values.addresses.length; index += 1) {
        const address = values.addresses[index];
        const label = t("customers.form.address.label", { index: index + 1 });

        if (isSender) {
          if (googleEnabled) {
            if (!isAddressVerified(address)) {
              return values.addresses.length > 1
                ? t("customers.form.validation.addressGoogleVerifyNamed", { label })
                : t("customers.form.validation.addressGoogleVerify");
            }
          } else if (!coreAddressRequiresVerification(address)) {
            return t("customers.form.validation.addressCompleteOrRemove", { label });
          }
        } else if (!address.city.trim()) {
          return t("customers.form.validation.addressCityRequired", { label });
        }
      }

      const duplicateAddressIndex = findDuplicateCustomerAddressIndex(values.addresses);
      if (duplicateAddressIndex >= 0) {
        return t("customers.form.validation.duplicateAddress", {
          label: t("customers.form.address.label", { index: duplicateAddressIndex + 1 }),
        });
      }
    }

    return null;
  })();

  /** Focus the first field that fails the same checks as `blockReason`. */
  function focusFirstInvalidField(current: CustomerFormValues = values) {
    if (!current.name.trim()) {
      focusFormField("name");
      return;
    }

    const firstPhone = current.phones[0];
    if (!firstPhone || !firstPhone.number.trim() || !isCompletePhoneNumber(firstPhone.number)) {
      focusFormField("customer-phone-number-0");
      return;
    }

    for (let index = 1; index < current.phones.length; index += 1) {
      const phone = current.phones[index];
      if (phone.number.trim() && !isCompletePhoneNumber(phone.number)) {
        focusFormField(`customer-phone-number-${index}`);
        return;
      }
    }

    const duplicatePhoneIndex = findDuplicateCustomerPhoneIndex(current.phones);
    if (duplicatePhoneIndex >= 0) {
      focusFormField(`customer-phone-number-${duplicatePhoneIndex}`);
      return;
    }

    if (showAddresses) {
      for (let index = 0; index < current.addresses.length; index += 1) {
        const address = current.addresses[index];

        if (isSender) {
          if (googleEnabled) {
            if (!isAddressVerified(address)) {
              focusFormField(`address-${index}-address1`);
              return;
            }
          } else if (!coreAddressRequiresVerification(address)) {
            focusFormField(`address-${index}-address1`);
            return;
          }
        } else if (!address.city.trim()) {
          focusFormField(`address-${index}-city`);
          return;
        }
      }

      const duplicateAddressIndex = findDuplicateCustomerAddressIndex(current.addresses);
      if (duplicateAddressIndex >= 0) {
        focusFormField(`address-${duplicateAddressIndex}-address1`);
        return;
      }
    }

    focusFormField("name");
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();

    const nextValues = normalizeCustomerFormValues(values);

    if (blockReason) {
      setFormError(blockReason);
      focusFirstInvalidField(nextValues);
      return;
    }

    try {
      validateCustomerFormValues(nextValues);
      setFormError(null);
      onSubmit(nextValues);
    } catch (error) {
      setFormError(
        error instanceof Error ? error.message : t("customers.form.validation.saveFailed"),
      );
      focusFirstInvalidField(nextValues);
    }
  }

  const selectedType = normalizeCustomerType(values.customerType);

  return (
    <form onSubmit={handleSubmit} onKeyDown={handleFormKeyDown} className="flex min-h-0 flex-1 flex-col">
      <FormBody isBusy={isSubmitting} className="@container min-h-0 space-y-5 p-4 sm:p-6">
        <div className="grid items-start gap-5 @3xl:h-full @3xl:grid-cols-2 @3xl:grid-rows-[minmax(0,1fr)]">
          <FormSection variant="card" icon={User} title={`01 · ${t("customers.form.workflow.contactTitle")}`}>
            <div className="grid gap-2.5">
              <div className="space-y-1">
                <Label htmlFor="customerType">
                  {t("customers.form.fields.customerType")} <span className="text-destructive">*</span>
                </Label>
                <SearchableSelect
                  id="customerType"
                  value={String(selectedType)}
                  onValueChange={(next) => handleCustomerTypeChange(Number(next))}
                  options={CUSTOMER_TYPE_OPTIONS.map((option) => ({
                    value: String(option.value),
                    label:
                      option.value === CUSTOMER_TYPE_SENDER
                        ? t("customers.types.sender")
                        : t("customers.types.receiver"),
                  }))}
                  disabled={lockCustomerType}
                  autoFocus={!isEditing && !lockCustomerType}
                  required
                  mobileSheet
                />
                {!lockCustomerType && showAddresses ? (
                  <p className="text-xs text-muted-foreground">{t("customers.form.workflow.typeChangeHint")}</p>
                ) : null}
              </div>

              <div className="space-y-1">
                <Label htmlFor="name">
                  {t("customers.form.fields.name")} <span className="text-destructive">*</span>
                </Label>
                <Input
                  id="name"
                  autoComplete="name"
                  value={values.name}
                  onChange={(event) => updateField("name", capitalizeWords(event.target.value))}
                  placeholder={t("customers.form.placeholders.name")}
                  autoFocus={!isEditing && lockCustomerType}
                  required
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="IDNumber">{t("customers.form.fields.idNumber")}</Label>
                <Input
                  id="IDNumber"
                  value={values.IDNumber}
                  onChange={(event) =>
                    updateField("IDNumber", event.target.value)
                  }
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="email">{t("customers.form.fields.email")}</Label>
                <Input
                  id="email"
                  type="email"
                  autoComplete="email"
                  value={values.email}
                  onChange={(event) => updateField("email", event.target.value)}
                  placeholder={t("customers.form.placeholders.email")}
                />
              </div>

              <div className="space-y-1">
                <Label htmlFor="notes">{t("customers.form.fields.notes")}</Label>
                <textarea
                  id="notes"
                  rows={3}
                  className="flex min-h-20 w-full resize-y rounded-md border border-input bg-card px-3 py-2 text-sm shadow-xs outline-none transition-colors placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 max-md:text-base"
                  value={values.notes}
                  onChange={(event) => updateField("notes", event.target.value)}
                  placeholder={t("customers.form.placeholders.notes")}
                />
              </div>
            </div>
          </FormSection>

          <div className="flex min-w-0 flex-col gap-5 @3xl:min-h-0 @3xl:self-stretch">
            <FormSection
              variant="card"
              icon={PhoneIcon}
              title={`02 · ${t("customers.form.sections.phones")}`}
              required
              className="shrink-0"
            >
              <PhoneListEditor
                idPrefix="customer-phone"
                phones={values.phones}
                required
                compact
                listClassName="-m-1 max-h-56 overflow-y-auto p-1"
                savedPhones={isEditing ? initialValues?.phones : undefined}
                onChange={(phones) => updateField("phones", phones)}
              />
            </FormSection>

            <FormSection
              variant="card"
              icon={MapPin}
              title={`03 · ${t("customers.form.sections.addresses")}`}
              className="flex flex-col @3xl:min-h-0 @3xl:flex-1"
            >
              <div className="flex min-h-0 flex-1 flex-col gap-3">
                {!showAddresses ? (
                  <div className="flex flex-col items-start gap-2 rounded-lg border border-dashed border-border bg-muted/20 p-5">
                    <div className="flex items-center gap-2">
                      <MapPin className="size-5 shrink-0 text-muted-foreground" aria-hidden="true" />
                      <p className="text-sm font-medium">{t("customers.form.workflow.addressEmptyTitle")}</p>
                    </div>
                    <p className="max-w-md text-sm leading-relaxed text-muted-foreground">{t("customers.form.workflow.addressEmptyHint")}</p>
                  </div>
                ) : null}
                {showAddresses ? (
                  <div className="-m-1 max-h-[32rem] min-h-0 space-y-3 overflow-y-auto p-1 @3xl:max-h-none @3xl:min-h-48 @3xl:flex-1">
                    {values.addresses.map((address, index) => {
                      const isPrimary = address.isPrimary;
                      const isUnsaved =
                        savedAddressKeys !== null &&
                        !savedAddressKeys.has(getCustomerAddressDuplicateKey(address));

                      return (
                        <div
                          key={index}
                          data-customer-address-index={index}
                          className={cn(
                            "rounded-lg border border-border/60 bg-muted/20 p-3",
                            isUnsaved && "border-dashed border-primary/50 bg-primary/[0.03]",
                          )}
                        >
                          <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
                            <div className="flex flex-wrap items-center gap-2">
                              <p className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                                {t("customers.form.address.label", { index: index + 1 })}
                              </p>
                              {isPrimary ? (
                                <span className="rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary">
                                  {t("customers.form.address.primaryBadge")}
                                </span>
                              ) : null}
                              {isSender ? <AddressVerificationBadge address={address} /> : null}
                              {isUnsaved ? (
                                <span className="rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary">
                                  {t("customers.form.address.unsavedBadge")}
                                </span>
                              ) : null}
                            </div>
                            <div className="flex items-center gap-1">
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                aria-pressed={isPrimary}
                                aria-label={isPrimary ? t("customers.form.address.primary") : t("customers.form.address.setPrimary")}
                                title={
                                  isPrimary
                                    ? t("customers.form.address.primary")
                                    : t("customers.form.address.setPrimary")
                                }
                                className={cn(
                                  "size-7 shrink-0",
                                  isPrimary
                                    ? "text-amber-500 hover:text-amber-500"
                                    : "text-muted-foreground",
                                )}
                                onClick={() => setPrimaryAddress(index)}
                              >
                                <Star className={cn("size-4", isPrimary && "fill-current")} />
                              </Button>
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                aria-label={t("customers.form.address.remove")}
                                title={t("customers.form.address.remove")}
                                className="size-7 shrink-0 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                                onClick={() => removeAddress(index)}
                              >
                                <Trash2 className="size-4" />
                              </Button>
                            </div>
                          </div>

                          <AddressFieldGrid
                            idPrefix={`address-${index}`}
                            address={address}
                            mode={addressMode}
                            onChange={(field, value) => updateAddressField(index, field, value)}
                            onPlaceSelected={(place) => applyPlaceToAddress(index, place)}
                            onCitySelected={(city) => applyCityToAddress(index, city)}
                          />
                        </div>
                      );
                    })}
                  </div>
                ) : null}

                <Button
                  type="button"
                  variant="outline"
                  className="h-9 w-full shrink-0 justify-center border-dashed border-primary/40 bg-card text-primary hover:bg-primary/10 hover:text-primary"
                  onClick={handleAddAddressClick}
                >
                  <Plus className="size-4" />
                  {t("customers.form.address.add")}
                </Button>
              </div>
            </FormSection>
          </div>
        </div>
      </FormBody>

      <FormFooter
        error={errorMessage}
        warning={blockReason}
        submitLabel={submitLabel}
        isSubmitting={isSubmitting}
        onCancel={onCancel}
      />
    </form>
  );
}

