                              {assigned
                                ? formatOrderRouteName(
                                    { routeId: stop.routeId, routeName: stop.routeName },
                                    getRouteByKey(stop.routeId),
                                    t,
                                  )
                                : t("orders.map.legend.unassigned")}
                            </span>
                          </span>
