                    <MapIcon className="h-4 w-4" />
                    {t("orders.actions.map")}
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={printSelectedOrders}
                    disabled={isPrinting}
                    className={cn("whitespace-nowrap", tableSelectionActionStyles.print)}
                  >
                    <Printer className="h-4 w-4" />
                    {isPrinting ? t("orders.actions.preparing") : t("orders.actions.print")}
                  </Button>
                  <TableSelectionActionDivider />
                </>
              ) : null}
              {!routesExpanded ? (
                <>
                  <TableSelectionExpandableActionGroup
                    label={t("orders.actions.manageCompletion")}
                    icon={CheckCircle2}
                    expanded={completionExpanded}
                    onExpandedChange={setCompletionExpanded}
                    aria-label={t("orders.actions.completionGroup")}
                  >
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={isSaving}
                      onClick={() => openCompletionConfirm(true)}
                      className="bg-emerald-500/5 text-emerald-700 hover:bg-emerald-500/10 hover:text-emerald-700 dark:text-emerald-300 dark:hover:text-emerald-300"
                    >
                      <CheckCircle2 className="h-4 w-4" />
                      {t("orders.actions.markComplete")}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={isSaving}
                      onClick={() => openCompletionConfirm(false)}
                      className="bg-amber-500/5 text-amber-700 hover:bg-amber-500/10 hover:text-amber-700 dark:text-amber-300 dark:hover:text-amber-300"
                    >
                      <XCircle className="h-4 w-4" />
                      {t("orders.actions.markIncomplete")}
                    </Button>
                  </TableSelectionExpandableActionGroup>
                  <TableSelectionActionDivider />
                </>
              ) : null}
              <TableSelectionExpandableActionGroup
                label={t("orders.actions.manageRoutes")}
                icon={RouteIcon}
                expanded={routesExpanded}
                onExpandedChange={(expanded) => {
                  setRoutesExpanded(expanded);
                  // Completion sits to the left — collapse it when routes takes the row.
                  if (expanded) setCompletionExpanded(false);
                }}
                aria-label={t("orders.actions.routeGroup")}
              >
                <Button
                  variant="outline"
                  size="sm"
                  disabled={isSaving}
                  onClick={openAssignRoute}
                >
                  <RouteIcon className="h-4 w-4" />
                  {t("orders.actions.assignRoute")}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={selectedOrdersWithRoute.length === 0}
                  onClick={viewSelectedRoute}
                  className={tableSelectionActionStyles.view}
                >
                  <Eye className="h-4 w-4" />
                  {t("orders.actions.viewRoute")}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={isSaving || selectedOrdersWithRoute.length === 0}
                  onClick={openClearRoute}
                  className="bg-amber-500/5 text-amber-700 hover:bg-amber-500/10 hover:text-amber-700 dark:text-amber-300 dark:hover:text-amber-300"
                >
                  <RouteOff className="h-4 w-4" />
                  {clearRouteMutation.isPending
                    ? t("orders.actions.clearingRoute")
                    : t("orders.actions.clearRoute")}
                </Button>
              </TableSelectionExpandableActionGroup>
            </>
          }
        />

        {isLoading ? (
          <DirectoryTableLoader
            icon={PackageOpen}
            title={t("orders.loading.title")}
            description={t("orders.loading.description")}
            columns={t("orders.loading.columns").split(", ")}
          />
        ) : (
          <DataTable
            columns={columnVisibility.columns}
            rows={orders}
            page={currentPage}
            isPageDataPending={isFetching}
            rowKey={(order) => getOrderRecordId(order)}
            rowLabel={(order) => formatOrderId(order)}
            columnLayout={columnVisibility}
            minWidth={1500}
            sort={sort}
            onSortChange={onSortChange}
            selectable
            selectedIds={selectedIds}
            allPageSelected={allPageSelected}
            onToggleSelectAll={toggleSelectAll}
            onToggleSelect={toggleSelect}
            renderSelectCellActions={(order) =>
              order.legacySyncStatus === "failed" ? (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-7 text-amber-700 hover:bg-amber-500/10 hover:text-amber-700 dark:text-amber-300 dark:hover:text-amber-300"
                  onClick={() => handleRetryLegacySync(order)}
                  disabled={retryLegacySyncMutation.isPending}
                  aria-label={t("orders.actions.retryLegacySync")}
                  title={order.legacySyncError || t("orders.actions.retryLegacySync")}
                >
                  <RefreshCw
                    className={cn("size-4", retryLegacySyncMutation.isPending && "animate-spin")}
                  />
                </Button>
              ) : null
            }
            onRowClick={openViewOrder}
            onRowDoubleClick={openEditForm}
            activeRowId={viewOrder ? getOrderRecordId(viewOrder) : undefined}
            emptyState={
              <>
                <p className="text-muted-foreground">{t("orders.empty.noMatch")}</p>
                <Button className="mt-4" onClick={openAddForm}>
                  <Plus className="h-4 w-4" />
                  {t("orders.actions.add")}
                </Button>
              </>
            }
          />
        )}

        {!isLoading ? (
        <div className="flex flex-col gap-3 border-t px-6 py-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="space-y-1">
            <p className="text-sm text-muted-foreground">{listSummary}</p>
          </div>
          <TablePaginationControls
            page={currentPage}
            totalPages={totalPages}
            pageSize={pageSize}
            onPageChange={setPage}
            onPageSizeChange={changePageSize}
            disabled={isLoading}
          />
        </div>
        ) : null}
        </Card>
      </div>

      <OrderViewSheet
        order={viewOrder}
        open={Boolean(viewOrder)}
        onOpenChange={(open) => {
          if (!open) setViewOrder(null);
        }}
        onEdit={openEditForm}
        onDelete={(order) => {
          setViewOrder(null);
          setDeleteTarget(order);
        }}
        onCreateInvoice={appointmentInvoice.canCreateInvoice ? createInvoiceFromOrder : undefined}
      />

      <AppointmentInvoiceDialogs state={appointmentInvoice} />

      <Dialog
        open={formMode !== null}
        onOpenChange={(open) => {
          if (!open) {
            setFormMode(null);
          }
        }}
      >
        <DialogContent className="flex h-[100dvh] max-h-[100dvh] w-screen max-w-none flex-col gap-0 overflow-hidden rounded-none p-0 max-md:[&>button.absolute]:hidden sm:h-auto sm:max-h-[90vh] sm:max-w-6xl sm:rounded-xl">
          <DialogHeader className="shrink-0 border-b border-primary/20 bg-primary px-4 pb-4 pt-5 text-primary-foreground sm:border-border sm:bg-background sm:px-6 sm:py-4 sm:text-foreground">
            <div className="flex items-center justify-between gap-4">
              <DialogTitle className="text-2xl font-bold text-primary-foreground sm:text-lg sm:text-foreground">
                {formMode === "edit" ? t("orders.form.editTitle") : t("orders.form.addTitle")}
              </DialogTitle>
              <button
                type="button"
                className="font-semibold text-primary-foreground sm:hidden"
                onClick={() => {
                  setFormMode(null);
                }}
              >
                {t("common.actions.cancel")}
              </button>
            </div>
            <DialogDescription className="text-primary-foreground/85 sm:hidden">
              {formMode === "edit" ? t("orders.actions.edit") : t("orders.form.addDescription")}
            </DialogDescription>
          </DialogHeader>
          <OrderForm
            key={editingOrder ? getOrderRecordId(editingOrder) : "new"}
            initialValues={
              formMode === "edit" && editingOrderFormValues
                ? editingOrderFormValues
                : emptyOrderFormValues
            }
            isEditing={formMode === "edit"}
            updatedAt={editingOrder?.updatedAt}
            submitLabel={formMode === "edit" ? t("common.actions.saveChanges") : t("orders.actions.add")}
            isSubmitting={isSaving}
            onSubmit={saveOrder}
            onCancel={() => {
              setFormMode(null);
            }}
          />
        </DialogContent>
      </Dialog>

      <AssignAppointmentRouteDialog
        open={assignRouteOpen}
        onOpenChange={setAssignRouteOpen}
        appointments={selectedOrders}
      />

      <Dialog
        open={completionConfirm !== null}
        onOpenChange={(open) => !open && setCompletionConfirm(null)}
      >
        <DialogContent className="z-[60]">
          <DialogHeader>
            <DialogTitle>
              {completionConfirm
                ? t("orders.dialogs.markCompleteTitle")
                : t("orders.dialogs.markIncompleteTitle")}
            </DialogTitle>
            <DialogDescription>
              {selectedOrders.length === 1
                ? t(
                    completionConfirm
                      ? "orders.dialogs.markCompleteDescription"
                      : "orders.dialogs.markIncompleteDescription",
                    { count: selectedOrders.length },
                  )
                : t(
                    completionConfirm
                      ? "orders.dialogs.markCompleteDescription_plural"
                      : "orders.dialogs.markIncompleteDescription_plural",
                    { count: selectedOrders.length },
                  )}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setCompletionConfirm(null)}
              disabled={setOrdersCompletedMutation.isPending}
            >
              {t("common.actions.cancel")}
            </Button>
            <Button
              onClick={() => completionConfirm !== null && void handleSetCompleted(completionConfirm)}
              disabled={setOrdersCompletedMutation.isPending}
              className={
                completionConfirm
                  ? "bg-emerald-600 text-white hover:bg-emerald-600/90"
                  : "bg-amber-600 text-white hover:bg-amber-600/90"
              }
            >
              {completionConfirm ? (
                <>
                  <CheckCircle2 className="h-4 w-4" />
                  {t("orders.actions.markComplete")}
                </>
              ) : (
                <>
                  <XCircle className="h-4 w-4" />
                  {t("orders.actions.markIncomplete")}
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog
        open={clearRouteOpen}
        onOpenChange={(open) => {
          if (clearRouteMutation.isPending) return;
          setClearRouteOpen(open);
        }}
      >
        <DialogContent
          className="z-[60]"
          onPointerDownOutside={(event) => {
            if (clearRouteMutation.isPending) event.preventDefault();
          }}
          onEscapeKeyDown={(event) => {
            if (clearRouteMutation.isPending) event.preventDefault();
          }}
        >
          <DialogHeader>
            <DialogTitle>{t("orders.dialogs.clearRouteTitle")}</DialogTitle>
            <DialogDescription>
              {selectedOrdersWithRoute.length === 1
                ? t("orders.dialogs.clearRouteDescription", {
                    count: selectedOrdersWithRoute.length,
                    cannotBeUndone: t("common.dialogs.cannotBeUndone"),
                  })
                : t("orders.dialogs.clearRouteDescription_plural", {
                    count: selectedOrdersWithRoute.length,
                    cannotBeUndone: t("common.dialogs.cannotBeUndone"),
                  })}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setClearRouteOpen(false)}
              disabled={clearRouteMutation.isPending}
            >
              {t("common.actions.cancel")}
            </Button>
            <ConfirmDeleteButton
              isPending={clearRouteMutation.isPending}
              onClick={() => void confirmClearRoute()}
              label={t("orders.actions.clearRoute")}
              pendingLabel={t("orders.actions.clearingRoute")}
              icon={RouteOff}
            />
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={deleteTarget !== null} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <DialogContent className="z-[60]">
          <DialogHeader>
            <DialogTitle>
              {Array.isArray(deleteTarget) && deleteTarget.length > 1
                ? t("orders.dialogs.deleteTitlePlural")
                : t("orders.dialogs.deleteTitle")}
            </DialogTitle>
            <DialogDescription>
              {Array.isArray(deleteTarget)
                ? t("orders.dialogs.deleteMany", {
                    count: deleteTarget.length,
                    cannotBeUndone: t("common.dialogs.cannotBeUndone"),
                  })
                : t("orders.dialogs.deleteOne", {
                    cannotBeUndone: t("common.dialogs.cannotBeUndone"),
                  })}
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteTarget(null)}>
              {t("common.actions.cancel")}
            </Button>
            <ConfirmDeleteButton isPending={isSaving} onClick={confirmDelete} />
          </DialogFooter>
        </DialogContent>
      </Dialog>

    </div>
    </>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { ChevronDown, ChevronRight, History, Loader2 } from "lucide-react";

import { normalizeApiError } from "@/lib/api/axios";
import { formatAuditDateTime } from "@/lib/audit/display";
import { useSenderOrderHistory } from "@/lib/orders/hooks/use-orders";
import {
  formatOrderCommentsSummary,
  formatOrderDate,
  formatUserSummary,
  getCustomerAddressLine,
  getReceiverAddressLine,
  getReceiverSummary,
} from "@/lib/orders/display";
import type { Customer } from "@/lib/customers/types";
import { cn } from "@/lib/utils";
import { useTranslation } from "@/lib/i18n";

type SenderOrderHistorySectionProps = {
  sender: Pick<Customer, "id" | "name">;
  currentOrderId?: string;
  variant?: "form" | "view" | "embedded";
};

export function SenderOrderHistorySection({
  sender,
  currentOrderId,
  variant = "form",
}: SenderOrderHistorySectionProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const senderId = sender.id.trim();
  const { data, isLoading, isError, error } = useSenderOrderHistory(senderId, {
    enabled: open || variant === "embedded",
  });

  useEffect(() => {
    setOpen(false);
  }, [senderId]);

  // The API already sorts by date desc; sort defensively in case that changes.
  const history = useMemo(
    () =>
      [...(data?.items ?? [])].sort(
        (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime(),
      ),
    [data?.items],
  );
  const senderName = sender.name.trim() || t("orders.history.defaultSenderName");
  const sectionTitle =
    data != null
      ? t("orders.history.title", { name: senderName, count: history.length })
      : t("orders.history.titleCollapsed", { name: senderName });
  const errorMessage = isError ? normalizeApiError(error).message : null;
  const dash = t("common.empty.dash");
  const toggleLabel = open ? t("orders.history.collapse") : t("orders.history.expand");
  const sectionId = "sender-appointment-history";
  const isView = variant === "view";

  const showTable = Boolean(senderId) && !isLoading && !errorMessage && history.length > 0;
  const headerClassName = cn(
    "px-3 py-2 font-medium",
    isView && "whitespace-nowrap",
  );
  const cellClassName = "px-3 py-2 text-xs text-foreground";

  const content = !senderId ? (
    <p className="text-sm text-muted-foreground">{t("orders.history.pendingSavedSender")}</p>
  ) : isLoading ? (
    <p className="flex items-center gap-2 text-sm text-muted-foreground">
      <Loader2 className="h-4 w-4 animate-spin" />
      {t("orders.loading.pickupHistory")}
    </p>
  ) : errorMessage ? (
    <p className="text-sm text-destructive">{errorMessage}</p>
  ) : history.length === 0 ? (
    <p className="text-sm text-muted-foreground">{t("orders.empty.noPickupHistory")}</p>
  ) : (
    <div className={cn("overflow-x-auto", !isView && "rounded-lg border")}>
      <table className={cn("w-full text-left", isView ? "text-xs" : "min-w-[760px] text-sm")}>
          <thead>
            <tr
              className={cn(
                "border-b text-muted-foreground",
                isView ? "bg-muted/40" : "bg-muted/50 text-xs",
              )}
            >
              <th className={headerClassName}>{t("orders.columns.date")}</th>
              <th className={headerClassName}>{t("orders.columns.senderAddressLine")}</th>
              <th className={headerClassName}>{t("orders.columns.comments")}</th>
              <th className={headerClassName}>{t("orders.columns.receiver")}</th>
              <th className={headerClassName}>{t("orders.columns.receiverAddress")}</th>
              <th className={headerClassName}>{t("orders.columns.createdAt")}</th>
              <th className={headerClassName}>{t("orders.columns.createdBy")}</th>
            </tr>
          </thead>
          <tbody>
            {history.map((order) => {
              const isCurrent = String(order.id) === currentOrderId;
              return (
                <tr
                  key={order.id}
                  className={cn(
                    "border-b last:border-b-0",
                    isView
                      ? "even:bg-muted/25"
                      : isCurrent
                        ? "bg-primary/5"
                        : "bg-background",
                  )}
                >
                  <td className={cn(cellClassName, "whitespace-nowrap")}>
                    {formatOrderDate(order.date)}
                    {isCurrent ? (
                      <span className="ml-2 text-[10px] text-primary">
                        {t("orders.history.current")}
                      </span>
                    ) : null}
                  </td>
                  <td className={cn(cellClassName, "min-w-[10rem] leading-snug [overflow-wrap:anywhere]")}>
                    {getCustomerAddressLine(order.sender)}
                  </td>
                  <td className={cn(cellClassName, "min-w-[8rem] leading-snug [overflow-wrap:anywhere]")}>
                    {order.comments.length > 0 ? formatOrderCommentsSummary(order) : dash}
                  </td>
                  <td className={cn(cellClassName, "whitespace-nowrap")}>{getReceiverSummary(order)}</td>
                  <td className={cn(cellClassName, "min-w-[10rem] leading-snug [overflow-wrap:anywhere]")}>
                    {getReceiverAddressLine(order)}
                  </td>
                  <td className={cn(cellClassName, "whitespace-nowrap", !isView && "text-muted-foreground")}>
                    {formatAuditDateTime(order.createdAt)}
                  </td>
                  <td className={cn(cellClassName, "whitespace-nowrap")}>{formatUserSummary(order.createdBy)}</td>
                </tr>
              );
            })}
          </tbody>
      </table>
    </div>
  );

  if (variant === "embedded") {
    return (
      <div className="min-w-0 space-y-2.5">
        <p className="text-sm text-muted-foreground">{sectionTitle}</p>
        {content}
      </div>
    );
  }

  return (
    <section
      className={cn(
        isView && "overflow-hidden rounded-lg border border-border bg-card shadow-sm",
        !isView && "space-y-2.5",
      )}
    >
      <button
        type="button"
        onClick={() => setOpen((current) => !current)}
        aria-expanded={open}
        aria-controls={`${sectionId}-panel`}
        title={toggleLabel}
        className={cn(
          "flex w-full items-center justify-between gap-2 text-left transition-colors",
          isView
            ? cn(
                "bg-muted/50 px-4 py-2.5 hover:bg-muted/70",
                open && "border-b border-border",
              )
            : "min-h-7 rounded-md hover:bg-muted/50",
        )}
      >
        <span className="flex min-w-0 items-center gap-2.5">
          {isView ? (
            <span className="h-3.5 w-0.5 shrink-0 rounded-full bg-primary/80" aria-hidden />
          ) : (
            <History className="size-4 shrink-0 text-primary" />
          )}
          <span
            className={cn(
              "truncate uppercase",
              isView
                ? "text-[11px] font-bold tracking-[0.1em] text-foreground/75"
                : "text-xs font-semibold tracking-wide text-muted-foreground",
            )}
          >
            {sectionTitle}
          </span>
        </span>
        <span className="inline-flex size-4 shrink-0 items-center justify-center text-muted-foreground">
          {open ? <ChevronDown className="size-4" /> : <ChevronRight className="size-4" />}
        </span>
      </button>
      {open ? (
        <div id={`${sectionId}-panel`} className={cn(isView && !showTable && "p-4")}>
          {content}
        </div>
      ) : null}
    </section>
  );
}

