"use client";

import { Plus, Star, Trash2 } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { PhoneInput } from "@/components/ui/phone-input";
import { SearchableSelect } from "@/components/ui/searchable-select";
import { useTranslation } from "@/lib/i18n";
import { cn } from "@/lib/utils";
import {
  createDefaultRecordPhones,
  createEmptyRecordPhone,
  ensureSinglePrimaryPhone,
} from "@/lib/phones/phones";
import { RECORD_PHONE_TYPE_OPTIONS, type RecordPhone } from "@/lib/phones/types";
import { getPhoneDialDigits } from "@/lib/utils/phone";

function savedPhoneKey(phone: Pick<RecordPhone, "type" | "number">): string {
  const digits = getPhoneDialDigits(phone.number);
  return digits ? `${phone.type}:${digits}` : "";
}

type PhoneListEditorProps = {
  idPrefix?: string;
  phones: RecordPhone[];
  required?: boolean;
  /** Dense single-row layout used inside compact forms. */
  compact?: boolean;
  /** Extra classes for the compact phone rows wrapper (e.g. a scroll cap). */
  listClassName?: string;
  /** Phones already persisted on the record; other rows are marked as not saved. */
  savedPhones?: RecordPhone[];
  onChange: (phones: RecordPhone[]) => void;
};

export function PhoneListEditor({
  idPrefix = "phone",
  phones,
  required = false,
  compact = false,
  listClassName,
  savedPhones,
  onChange,
}: PhoneListEditorProps) {
  const { t } = useTranslation();
  const entries = phones.length > 0 ? phones : createDefaultRecordPhones();
  const [pendingFocusIndex, setPendingFocusIndex] = useState<number | null>(null);

  const savedPhoneKeys = useMemo(
    () => (savedPhones ? new Set(savedPhones.map(savedPhoneKey).filter(Boolean)) : null),
    [savedPhones],
  );
  const isUnsavedPhone = (phone: RecordPhone) =>
    savedPhoneKeys !== null && !savedPhoneKeys.has(savedPhoneKey(phone));

  const phoneTypeOptions = useMemo(
    () =>
      RECORD_PHONE_TYPE_OPTIONS.map((option) => ({
        value: option.value,
        label: t(`phones.types.${option.value}`),
      })),
    [t],
  );

  useEffect(() => {
    if (pendingFocusIndex == null) return;
    const input = document.getElementById(`${idPrefix}-number-${pendingFocusIndex}`);
    if (!input) return;
    input.focus();
    setPendingFocusIndex(null);
  }, [pendingFocusIndex, entries.length, idPrefix]);

  function updatePhone(index: number, patch: Partial<RecordPhone>) {
    const next = entries.map((phone, phoneIndex) => {
      if (phoneIndex === index) {
        return { ...phone, ...patch };
      }
      // When marking a phone as primary, clear the flag on all others so the
      // newly selected one wins (avoids reverting to the first existing primary).
      return patch.isPrimary ? { ...phone, isPrimary: false } : phone;
    });
    onChange(patch.isPrimary ? ensureSinglePrimaryPhone(next) : next);
  }

  function addPhone() {
    const newIndex = entries.length;
    onChange([...entries, createEmptyRecordPhone(false)]);
    setPendingFocusIndex(newIndex);
  }

  function removePhone(index: number) {
    if (entries.length <= 1) {
      onChange(createDefaultRecordPhones());
      return;
    }

    onChange(ensureSinglePrimaryPhone(entries.filter((_, phoneIndex) => phoneIndex !== index)));
  }

  if (compact) {
    return (
      <div className="flex flex-col gap-3">
        <div className={cn("space-y-2.5", listClassName)}>
          {entries.map((phone, index) => {
            const isOnly = entries.length <= 1;
            const isUnsaved = isUnsavedPhone(phone);

            return (
              <div key={`${idPrefix}-${index}`} className="flex items-center gap-2.5">
                <div className="w-36 shrink-0 sm:w-40">
                  <SearchableSelect
                    aria-label={t("phones.aria.type", { index: index + 1 })}
                    value={phone.type}
                    onValueChange={(next) => updatePhone(index, { type: next as RecordPhone["type"] })}
                    searchPlaceholder={t("phones.searchTypes")}
                    options={phoneTypeOptions}
                  />
                </div>

                <div className="relative min-w-0 flex-1">
                  <PhoneInput
                    id={`${idPrefix}-number-${index}`}
                    aria-label={t("phones.aria.number", { index: index + 1 })}
                    aria-describedby={isUnsaved ? `${idPrefix}-unsaved-${index}` : undefined}
                    value={phone.number}
                    onChange={(nextValue) => updatePhone(index, { number: nextValue })}
                    required={required && index === 0}
                    className={cn(isUnsaved && "border-dashed border-primary/50 bg-primary/[0.03] pr-24")}
                  />
                  {isUnsaved ? (
                    <span
                      id={`${idPrefix}-unsaved-${index}`}
                      className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2 rounded-full bg-primary/10 px-2 py-0.5 text-[11px] font-medium text-primary"
                    >
                      {t("phones.unsaved")}
                    </span>
                  ) : null}
                </div>

                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  aria-pressed={phone.isPrimary}
                  title={phone.isPrimary ? t("phones.primary") : t("phones.setPrimary")}
                  className={cn(
                    "shrink-0",
                    phone.isPrimary
                      ? "text-amber-500 hover:text-amber-500"
                      : "text-muted-foreground",
                  )}
                  onClick={() => updatePhone(index, { isPrimary: true })}
                >
                  <Star className={cn("size-4", phone.isPrimary && "fill-current")} />
                </Button>

                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  title={t("phones.remove")}
                  disabled={isOnly}
                  className="shrink-0 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  onClick={() => removePhone(index)}
                >
                  <Trash2 className="size-4" />
                </Button>
              </div>
            );
          })}
        </div>

        <Button
          type="button"
          variant="outline"
          className="h-9 w-full shrink-0 justify-center border-dashed border-primary/40 bg-card text-primary hover:bg-primary/10 hover:text-primary"
          onClick={addPhone}
        >
          <Plus className="size-4" />
          {t("phones.add")}
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {entries.map((phone, index) => (
        <div key={`${idPrefix}-${index}`} className="rounded-lg border border-border/70 p-4">
          <div className="mb-3 flex items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <p className="text-sm font-medium">{t("phones.label", { index: index + 1 })}</p>
              {isUnsavedPhone(phone) ? (
                <span className="rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary">
                  {t("phones.unsaved")}
                </span>
              ) : null}
            </div>
            {entries.length > 1 ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                className="border-destructive/35 text-destructive hover:bg-destructive/10 hover:text-destructive"
                onClick={() => removePhone(index)}
              >
                <Trash2 className="size-4" />
                {t("phones.removeButton")}
              </Button>
            ) : null}
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor={`${idPrefix}-type-${index}`}>{t("phones.fieldType")}</Label>
              <SearchableSelect
                id={`${idPrefix}-type-${index}`}
                value={phone.type}
                onValueChange={(next) => updatePhone(index, { type: next as RecordPhone["type"] })}
                searchPlaceholder={t("phones.searchTypes")}
                options={phoneTypeOptions}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor={`${idPrefix}-number-${index}`}>
                {t("phones.fieldNumber")}{" "}
                {required && index === 0 ? <span className="text-destructive">*</span> : null}
              </Label>
              <PhoneInput
                id={`${idPrefix}-number-${index}`}
                value={phone.number}
                onChange={(nextValue) => updatePhone(index, { number: nextValue })}
                required={required && index === 0}
              />
            </div>
          </div>

          <label className="mt-3 flex items-center gap-2 text-sm">
            <input
              type="radio"
              name={`${idPrefix}-primary`}
              checked={phone.isPrimary}
              onChange={() => updatePhone(index, { isPrimary: true })}
            />
            {t("phones.primary")}
          </label>
        </div>
      ))}

      <Button
        type="button"
        variant="outline"
        size="sm"
        className="border-primary/40 text-primary hover:bg-primary/10 hover:text-primary"
        onClick={addPhone}
      >
        <Plus className="size-4" />
        {t("phones.add")}
      </Button>
    </div>
  );
}

