"use client";

import { useEffect, useMemo, useState } from "react";
import type { ComponentType, ReactNode } from "react";
import {
  Anchor,
  ArrowLeft,
  BadgeDollarSign,
  Box,
  BriefcaseBusiness,
  CalendarDays,
  ChevronRight,
  CircleDollarSign,
  ClipboardList,
  Container,
  FileSpreadsheet,
  FileText,
  FileType,
  LoaderCircle,
  MapPin,
  PackageCheck,
  ReceiptText,
  SearchX,
  User,
  UsersRound,
  X,
} from "lucide-react";

import { PageHeader } from "@/components/app-shell/page-header";
